public int maxSubArray(int[] nums) {
    int current = nums[0], best = nums[0];
    for (int i = 1; i < nums.length; i++) {
        current = Math.max(nums[i], current + nums[i]);
        best = Math.max(best, current);
    }
    return best;
}

public int climbStairs(int n) {
    int a=1, b=1;
    for (int i=2; i<=n; i++) { int next=a+b; a=b; b=next; }
    return b;
}

public int coinChange(int[] coins, int amount) {
    int[] dp = new int[amount+1];
    Arrays.fill(dp, amount+1);
    dp[0]=0;
    for (int a=1; a<=amount; a++)
        for (int c : coins)
            if (c<=a) dp[a]=Math.min(dp[a], dp[a-c]+1);
    return dp[amount]>amount ? -1 : dp[amount];
}

public int numIslands(char[][] grid) {
    if (grid.length == 0) return 0;
    int rows=grid.length, cols=grid[0].length, count=0;
    int[][] dirs={{1,0},{-1,0},{0,1},{0,-1}};
    for (int r=0;r<rows;r++) for (int c=0;c<cols;c++) {
        if (grid[r][c]!='1') continue;
        count++;
        Deque<int[]> stack=new ArrayDeque<>();
        stack.push(new int[]{r,c}); grid[r][c]='0';
        while (!stack.isEmpty()) {
            int[] p=stack.pop();
            for (int[] d:dirs) {
                int nr=p[0]+d[0], nc=p[1]+d[1];
                if (nr>=0 && nr<rows && nc>=0 && nc<cols && grid[nr][nc]=='1') {
                    grid[nr][nc]='0'; stack.push(new int[]{nr,nc});
                }
            }
        }
    }
    return count;
}

public int[][] merge(int[][] intervals) {
    if (intervals.length==0) return new int[0][];
    Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));
    List<int[]> out=new ArrayList<>();
    int[] cur=intervals[0].clone();
    for (int i=1;i<intervals.length;i++) {
        if (intervals[i][0]<=cur[1]) cur[1]=Math.max(cur[1],intervals[i][1]);
        else { out.add(cur); cur=intervals[i].clone(); }
    }
    out.add(cur);
    return out.toArray(new int[0][]);
}

public int findKthLargest(int[] nums, int k) {
    PriorityQueue<Integer> pq=new PriorityQueue<>();
    for (int n:nums) { pq.offer(n); if (pq.size()>k) pq.poll(); }
    return pq.peek();
}

public int rob(int[] nums) {
    int prev2=0, prev1=0;
    for (int n:nums) { int next=Math.max(prev1,prev2+n); prev2=prev1; prev1=next; }
    return prev1;
}
